#include <Eigen/Dense>
#include <iostream>
#include <cmath>
#include <iomanip>

using namespace Eigen;

static const double DCR = 0.017453292;

int main() {
    // Test case inputs
    Vector3d gA(1.0, 0.0, 0.0);
    Vector3d gB(0.0, 0.0, 1.0);
    Vector3d Vref(0.0, 1.0, 0.0);
    double R = 1.0;
    double BETAR = 90.0; // degrees
    double E = 200e9;
    double nu = 0.3;
    double G = E / (2.0 * (1.0 + nu));

    double ro = 0.05;
    double t = 0.005;
    double ri = ro - t;
    double A = M_PI * (ro*ro - ri*ri);
    double I1 = M_PI / 4.0 * (std::pow(ro,4) - std::pow(ri,4));
    double I2 = I1;
    double FJ = 2.0 * I1;

    // Flexibility correction factors (default 1.0)
    double KX = 1.0, KY = 1.0, KZ = 1.0;
    double K1 = 1.0, K2 = 1.0;

    // Build local coordinate system
    // VECJ = normalized reference vector
    Vector3d VECJ = Vref.normalized();

    // SMALV0 = B - A normalized
    Vector3d SMALV0 = (gB - gA).normalized();

    // VECK = SMALV0 x VECJ
    Vector3d VECK = SMALV0.cross(VECJ);
    VECK.normalize();

    // VECI = VECJ x VECK
    Vector3d VECI = VECJ.cross(VECK);
    VECI.normalize();

    // Section property constants
    double T = BETAR * DCR;
    double RA  = R / (A * E);
    double RV1 = R / (2.0 * K1 * G * A);
    double RV2 = K1 / K2 * RV1;
    double RT  = R / (G * FJ * 2.0);
    double RB0 = R / (E * I2 * 2.0);
    double RB1 = R / (E * I1);
    double R2  = R * R;

    double ST  = std::sin(T);
    double CT  = std::cos(T);
    double S2T = std::sin(2.0 * T);
    double C2T = std::cos(2.0 * T);

    // Build flexibility matrix F (upper triangle)
    MatrixXd F = MatrixXd::Zero(6,6);

    // Axial
    F(0,0) += 0.25*RA*(2.0*T + S2T);
    F(1,1) += 0.25*RA*(2.0*T - S2T);
    F(0,1) += 0.50*RA*ST*ST;

    // Shear
    F(0,0) += 0.5*RV1*(2.0*T - S2T);
    F(1,1) += 0.5*RV1*(2.0*T + S2T);
    F(2,2) += 2.0*RV2*T;
    F(0,1) -= RV1*ST*ST;

    // Torsion
    F(2,2) += 0.5*RT*R2*(6.0*T + S2T - 8.0*ST);
    F(3,3) += 0.5*RT*(2.0*T + S2T);
    F(4,4) += 0.5*RT*(2.0*T - S2T);
    F(2,3) += RT*R*(ST - T*CT);
    F(2,4) += RT*R*(2.0 - 2.0*CT - T*ST);
    F(3,4) += 0.5*RT*(1.0 - C2T);

    // Bending
    F(0,0) += 0.25*RB1*R2*(2.0*T*(2.0 + C2T) - 3.0*S2T);
    F(1,1) += 0.25*RB1*R2*(2.0*T*(2.0 - C2T) + 3.0*S2T - 8.0*ST);
    F(2,2) += 0.50*RB0*R2*(2.0*T - S2T);
    F(3,3) += 0.50*RB0*(2.0*T - S2T);
    F(4,4) += 0.50*RB0*(2.0*T + S2T);
    F(5,5) += RB1*T;
    F(0,1) += 0.25*RB1*R2*(1.0 + 3.0*C2T + 2.0*T*S2T - 4.0*CT);
    F(0,5) -= RB1*R*(ST - T*CT);
    F(1,5) += RB1*R*(T*ST + CT - 1.0);
    F(2,3) += RB0*R*(ST - T*CT);
    F(2,4) -= RB0*R*T*ST;
    F(3,4) -= 0.50*RB0*(1.0 - C2T);

    // Form symmetric DF
    MatrixXd DF = MatrixXd::Zero(6,6);
    for (int i = 0; i < 6; i++)
        for (int k = i; k < 6; k++) {
            DF(k,i) = F(i,k);
            DF(i,k) = DF(k,i);
        }

    // Invert F to get stiffness
    MatrixXd DFinv = DF.inverse();

    // Build H transformation
    MatrixXd H = MatrixXd::Zero(6,6);
    for (int k = 0; k < 6; k++) H(k,k) = -1.0;
    H(3,2) = -R*(1.0 - CT);
    H(4,2) = R*ST;
    H(5,0) = -H(3,2);
    H(5,1) = -H(4,2);

    // Form S (12x12)
    MatrixXd S = MatrixXd::Zero(12,12);

    // S(K+6, I+6) = DF(K,I)  (1-indexed -> 0-indexed: S[k+6][i+6])
    for (int k = 0; k < 6; k++)
        for (int i = k; i < 6; i++)
            S(k+6, i+6) = DFinv(k,i);

    // S(IR, IC+6) = sum H(IR,IN)*DF(IN,IC)
    for (int ir = 0; ir < 6; ir++)
        for (int ic = 0; ic < 6; ic++) {
            double sum = 0.0;
            for (int in = 0; in < 6; in++)
                sum += H(ir,in) * DFinv(in,ic);
            S(ir, ic+6) = sum;
        }

    // S(IR, IC) = sum S(IR, IN+6)*H(IC, IN)
    for (int ir = 0; ir < 6; ir++)
        for (int ic = ir; ic < 6; ic++) {
            double sum = 0.0;
            for (int in = 0; in < 6; in++)
                sum += S(ir, in+6) * H(ic, in);
            S(ir, ic) = sum;
        }

    // Reflect for symmetry
    for (int i = 0; i < 12; i++)
        for (int k = i; k < 12; k++)
            S(k,i) = S(i,k);

    // Now build the transformation matrix A^T (VECI, VECJ, VECK)
    // KE(1..9) = A^T matrix (3x3)
    Matrix3d AT;
    AT(0,0)=VECI(0); AT(0,1)=VECI(1); AT(0,2)=VECI(2);
    AT(1,0)=VECJ(0); AT(1,1)=VECJ(1); AT(1,2)=VECJ(2);
    AT(2,0)=VECK(0); AT(2,1)=VECK(1); AT(2,2)=VECK(2);

    // W matrix: 6x6 with G in upper-left and lower-right corners
    // G = AT (since basic coords, no TRANSD)
    MatrixXd G6 = MatrixXd::Zero(6,6);
    G6.block<3,3>(0,0) = AT;
    G6.block<3,3>(3,3) = AT;

    // Final stiffness: K = W^T * S * W
    MatrixXd K = G6.transpose() * S * G6;

    // Output as JSON
    std::cout << std::setprecision(10);
    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 12; i++) {
        std::cout << "[";
        for (int j = 0; j < 12; j++) {
            std::cout << std::scientific << K(i,j);
            if (j < 11) std::cout << ",";
        }
        std::cout << "]";
        if (i < 11) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
}
